-- pad-collision-probes.sql (repair-padbatch4). READ-ONLY. NOT EXECUTED by the worker.
-- Run manually on the PG copy (schema newvillacarmen_business). Every query returns aggregate COUNTS only, never values.
-- Keys = the 116 RequiredPadKeyIndexes (internal/db/padkeys.go) + 18 PAD PKs (full column set) + every FK child of those PKs.
-- collision_groups / rows_in_collisions: groups equal under the future ixpad key; nullable parts filtered IS NOT NULL
--   (uniques treat NULL as distinct). padded_rows: values ending in ASCII space, via octet_length.
-- CHAR(n) columns: PG bpchar ignores trailing spaces on read/compare, so padded_rows is NULL there; use the MySQL twin.
BEGIN READ ONLY;
-- 116 required unique keys
SELECT 'restaurant_domains.ixpad__restaurant_domains__uniq_restaurant_domains_domain' AS probe, (SELECT count(*) FROM (SELECT count(*) AS n FROM "restaurant_domains" GROUP BY (rtrim("domain", ' ') COLLATE dbmigrate.ci_ai) HAVING count(*) > 1) g) AS collision_groups, (SELECT COALESCE(sum(n),0) FROM (SELECT count(*) AS n FROM "restaurant_domains" GROUP BY (rtrim("domain", ' ') COLLATE dbmigrate.ci_ai) HAVING count(*) > 1) g) AS rows_in_collisions, (SELECT count(*) FROM "restaurant_domains" WHERE octet_length("domain") <> octet_length(rtrim("domain", ' '))) AS padded_rows;
